  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { topWords } = require('../src/textstats');
  4	
  5	// "keeper" x3, "lamp" x3, "night" x2, "tower" x2, "storm" x1. Stop words
  6	// (the, a, of, and, on, in, was) are present on purpose and must not appear.
  7	const PASSAGE = [
  8	  'The keeper lit the lamp. The lamp was old, and the keeper was older.',
  9	  'On a night of storm the tower shook; in the night the keeper climbed',
 10	  'the tower, lamp in hand.',
 11	].join(' ');
 12	
 13	const CASES = [
 14	  ["apple", 1, [{"word": "apple", "count": 1}]],
 15	  ["apple apple", 1, [{"word": "apple", "count": 2}]],
 16	  ["apple banana", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 17	  ["banana apple", 5, [{"word": "apple", "count": 1}, {"word": "banana", "count": 1}]],
 18	  ["fig fig pear", 1, [{"word": "fig", "count": 2}]],
 19	  ["fig fig pear", 2, [{"word": "fig", "count": 2}, {"word": "pear", "count": 1}]],
 20	  ["kiwi kiwi lime lime", 2, [{"word": "kiwi", "count": 2}, {"word": "lime", "count": 2}]],
 21	  ["x y z", 2, [{"word": "x", "count": 1}, {"word": "y", "count": 1}]],
 22	];
 23	
 24	test('returns an empty array for the empty string', () => {
 25	  assert.deepEqual(topWords('', 5), []);
 26	});
 27	
 28	test('returns an empty array for punctuation and whitespace only', () => {
 29	  assert.deepEqual(topWords(' ... -- ?! \n', 5), []);
 30	});
 31	
 32	test('returns an empty array when every word is a stop word', () => {
 33	  assert.deepEqual(topWords('the and of the to a in it', 5), []);
 34	});
 35	
 36	test('returns an empty array when n is 0', () => {
 37	  assert.deepEqual(topWords('apple banana apple', 0), []);
 38	});
 39	
 40	test('returns word and count pairs', () => {
 41	  assert.deepEqual(topWords('apple', 1), [{ word: 'apple', count: 1 }]);
 42	});
 43	
 44	test('orders words by count, highest first', () => {
 45	  assert.deepEqual(topWords('pear apple apple fig fig fig', 3), [
 46	    { word: 'fig', count: 3 },
 47	    { word: 'apple', count: 2 },
 48	    { word: 'pear', count: 1 },
 49	  ]);
 50	});
 51	
 52	test('throws a TypeError naming the function for a non-string', () => {
 53	  for (const bad of [undefined, null, 3, {}, ['apple']]) {
 54	    assert.throws(() => topWords(bad, 3), (err) => {
 55	      assert.ok(err instanceof TypeError);
 56	      assert.ok(err.message.startsWith('topWords:'));
 57	      return true;
 58	    });
 59	  }
 60	});
 61	
 62	test('matches every row of the reference table', () => {
 63	  for (const [text, n, expected] of CASES) {
 64	    assert.deepEqual(topWords(text, n), expected, JSON.stringify([text, n]));
 65	  }
 66	});
 67	
 68	test('ranks the passage by count and then alphabetically without stop words', () => {
 69	  assert.deepEqual(topWords(PASSAGE, 100), [
 70	    { word: 'keeper', count: 3 },
 71	    { word: 'lamp', count: 3 },
 72	    { word: 'night', count: 2 },
 73	    { word: 'tower', count: 2 },
 74	    { word: 'climbed', count: 1 },
 75	    { word: 'hand', count: 1 },
 76	    { word: 'lit', count: 1 },
 77	    { word: 'old', count: 1 },
 78	    { word: 'older', count: 1 },
 79	    { word: 'shook', count: 1 },
 80	    { word: 'storm', count: 1 },
 81	  ]);
 82	});
 83	
 84	test('returns only the first n entries of the passage ranking', () => {
 85	  assert.deepEqual(topWords(PASSAGE, 3), [
 86	    { word: 'keeper', count: 3 },
 87	    { word: 'lamp', count: 3 },
 88	    { word: 'night', count: 2 },
 89	  ]);
 90	});
 91	
 92	test('returns every distinct word when n exceeds their number', () => {
 93	  assert.equal(topWords('apple banana apple', 50).length, 2);
 94	});
 95	
 96	test('throws a RangeError naming the function for an invalid n', () => {
 97	  for (const bad of [undefined, NaN, '3', 1.5, -1]) {
 98	    assert.throws(() => topWords('apple', bad), (err) => {
 99	      assert.ok(err instanceof RangeError);
100	      assert.ok(err.message.startsWith('topWords:'));
101	      return true;
102	    });
103	  }
104	});
105	
106	test('checks the text before n', () => {
107	  assert.throws(() => topWords(42, 'bad'), TypeError);
108	});
109	
110	test('folds case so Éclair and éclair are one entry', () => {
111	  assert.deepEqual(topWords('Éclair éclair ÉCLAIR', 5), [{ word: 'éclair', count: 3 }]);
112	});
113	
114	test('folds the typographic apostrophe so keeper’s and keeper\'s are one entry', () => {
115	  assert.deepEqual(topWords("keeper’s keeper's", 5), [{ word: "keeper's", count: 2 }]);
116	});
117	
118	test('keeps hyphenated compounds, contractions and numbers whole', () => {
119	  assert.deepEqual(topWords("well-known don't 42 well-known", 5), [
120	    { word: 'well-known', count: 2 },
121	    { word: '42', count: 1 },
122	    { word: "don't", count: 1 },
123	  ]);
124	});
125	
126	test('returns fresh objects on every call', () => {
127	  const first = topWords('apple apple pear', 2);
128	  first[0].count = 99;
129	  first[0].word = 'changed';
130	  first.pop();
131	  assert.deepEqual(topWords('apple apple pear', 2), [
132	    { word: 'apple', count: 2 },
133	    { word: 'pear', count: 1 },
134	  ]);
135	});
  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { readingTimeMinutes, wordCount } = require('../src/textstats');
  4	
  5	// n copies of a one-word token, so the word count is exactly n.
  6	const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  7	
  8	const CASES = [
  9	  ["", null, 0],
 10	  ["x", null, 1],
 11	  ["x x", null, 1],
 12	  ["", 50, 0],
 13	  ["x", 1, 1],
 14	  ["x x", 1, 2],
 15	  ["x x x", 1, 3],
 16	  ["x x x", 2, 2],
 17	];
 18	
 19	test('returns 0 for the empty string', () => {
 20	  assert.equal(readingTimeMinutes(''), 0);
 21	});
 22	
 23	test('returns 0 for whitespace and punctuation only', () => {
 24	  assert.equal(readingTimeMinutes(' \n -- ... '), 0);
 25	});
 26	
 27	test('rounds a single word up to one minute', () => {
 28	  assert.equal(readingTimeMinutes('hello'), 1);
 29	});
 30	
 31	test('returns 1 for exactly 200 words at the default rate', () => {
 32	  assert.equal(readingTimeMinutes(words(200)), 1);
 33	});
 34	
 35	test('returns 2 for 201 words at the default rate', () => {
 36	  assert.equal(readingTimeMinutes(words(201)), 2);
 37	});
 38	
 39	test('returns 2 for exactly 400 words at the default rate', () => {
 40	  assert.equal(readingTimeMinutes(words(400)), 2);
 41	});
 42	
 43	test('throws a TypeError naming the function for a non-string', () => {
 44	  for (const bad of [undefined, null, 12, {}, ['a b']]) {
 45	    assert.throws(() => readingTimeMinutes(bad), (err) => {
 46	      assert.ok(err instanceof TypeError);
 47	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
 48	      return true;
 49	    });
 50	  }
 51	});
 52	
 53	test('matches every row of the reference table', () => {
 54	  for (const [text, wpm, expected] of CASES) {
 55	    const actual = wpm === null ? readingTimeMinutes(text) : readingTimeMinutes(text, wpm);
 56	    assert.equal(actual, expected, JSON.stringify([text, wpm]));
 57	  }
 58	});
 59	
 60	test('returns 2 for three paragraphs totalling 270 words', () => {
 61	  const paragraph = Array.from({ length: 10 }, () => 'The quick brown fox jumps over the lazy dog.').join(' ');
 62	  const text = [paragraph, paragraph, paragraph].join('\n\n');
 63	  assert.equal(wordCount(text), 270);
 64	  assert.equal(readingTimeMinutes(text), 2);
 65	});
 66	
 67	test('throws a RangeError naming the function for a rate that is not a positive finite number', () => {
 68	  for (const bad of [0, -1, -200, NaN, Infinity, -Infinity, '200', null, true, {}, [200], 10n]) {
 69	    assert.throws(() => readingTimeMinutes('hello world', bad), (err) => {
 70	      assert.ok(err instanceof RangeError, `expected RangeError for ${String(bad)}`);
 71	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
 72	      return true;
 73	    });
 74	  }
 75	});
 76	
 77	test('treats an explicit undefined rate as the default of 200', () => {
 78	  assert.equal(readingTimeMinutes(words(201), undefined), 2);
 79	  assert.equal(readingTimeMinutes(words(200), undefined), 1);
 80	});
 81	
 82	test('allows a fractional rate', () => {
